package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.exceptions.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeColumn_TriageGen2Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveColumn_ColumnDoesNotExist_ThrowsException() {
        // Add some data to ensure the dataset is not empty
        dataset.addObject("Value", "Row1", "Col1");

        try {
            dataset.removeColumn("NonExistentCol");
            org.junit.Assert.fail("Expected UnknownKeyException was not thrown");
        } catch (UnknownKeyException e) {
            assertEquals("Column key (NonExistentCol) not recognised.", e.getMessage());
        }
    }

    @Test
    public void testRemoveColumn_SuccessfulRemoval() {
        // Setup columns and rows
        String col1 = "Col1";
        String col2 = "Col2";
        String row1 = "Row1";
        String row2 = "Row2";

        dataset.addObject("V1_1", row1, col1);
        dataset.addObject("V1_2", row1, col2);
        dataset.addObject("V2_1", row2, col1);
        dataset.addObject("V2_2", row2, col2);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals(2, dataset.getRowCount());
        assertEquals("V1_2", dataset.getObject(row1, col2));

        // Execute removal
        dataset.removeColumn(col1);

        // Verify column is removed from columnKeys list
        assertEquals(1, dataset.getColumnCount());
        assertEquals(col2, dataset.getColumnKey(0));

        // Verify data is removed from rows
        // Since col1 was removed, row1 now only has col2. 
        // Depending on implementation of KeyedObjects, the index or presence of col1 should be gone.
        assertNull(dataset.getObject(row1, col1));
        assertEquals("V1_2", dataset.getObject(row1, col2));
        assertEquals("V2_2", dataset.getObject(row2, col2));
    }

    @Test
    public void testRemoveColumn_ColumnExistsButRowDoesNotContainKey() {
        // This tests the branch: if (i >= 0) inside the while loop
        // We need a row that doesn't have the specific column key index
        String col1 = "Col1";
        String col2 = "Col2";
        String row1 = "Row1";

        dataset.addObject("V1_1", row1, col1);
        // We manually add a row or use a way to ensure a row exists that doesn't have col2
        // However, in KeyedObjects2D, addObject adds the key. 
        // To hit the 'i < 0' branch, we need a row object in 'rows' that doesn't contain the columnKey.

        // Since we can't easily inject a raw KeyedObjects without the key, 
        // we rely on the logic that if the row exists but the key index is -1.

        dataset.addObject("V1_1", row1, col1);

        // The current implementation of addObject usually ensures the key is there.
        // But if a row was added via another method or if the key was removed from the row specifically:
        // We will test the scenario where the column exists in the dataset but a specific row doesn't have it.

        // Create a second row that doesn't have col2
        dataset.addObject("V2_1", "Row2", col1);

        // Now remove col2 (which exists in the dataset because of Row1)
        // Wait, if col2 is in the dataset, it means at least one row has it.
        // If we add a row that only has col1, the iterator will hit that row, 
        // getIndex(col2) will return -1, and it should skip rowData.removeValue(i).

        dataset.addObject("V1_2", row1, col2);

        // Row2 only has col1.
        dataset.removeColumn(col2);

        assertEquals(1, dataset.getColumnCount());
        assertEquals(col1, dataset.getColumnKey(0));
        assertNull(dataset.getObject(row1, col2));
    }

    @Test
    public void testRemoveColumn_EmptyDataset() {
        // Testing removal on an empty dataset (though getColumnIndex would likely return -1)
        try {
            dataset.removeColumn("Any");
        } catch (UnknownKeyException e) {
            // Expected behavior for empty dataset
        }
    }
}
